import{_ as i,a0 as s,w as a,s as l,ao as p,I as n,x as o,a1 as r,A as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"安卓編年史（18）：Android 4.0 冰淇淋三明治—摩登時代 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（18）：Android 4.0 冰淇淋三明治—摩登時代 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（18）：Android 4.0 冰淇淋三明治—摩登時代 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（18）：Android 4.0 冰淇淋三明治—摩登時代 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/19 - The history of Android","title":"安卓編年史（18）：Android 4.0 冰淇淋三明治—摩登時代","tag":"The history of Android","desc":""},"relativePath":"The history of Android/19 - The history of Android.md","filePath":"[post].md"}'),u={name:"The history of Android/19 - The history of Android.md"};function m(f,t,g,x,T,A){const e=s("Link");return a(),l("div",null,[t[19]||(t[19]=p('<h1 id="安卓編年史-18-android-4-0-冰淇淋三明治—摩登時代" tabindex="-1">安卓編年史（18）：Android 4.0 冰淇淋三明治—摩登時代 <a class="header-anchor" href="#安卓編年史-18-android-4-0-冰淇淋三明治—摩登時代" aria-label="Permalink to “安卓編年史（18）：Android 4.0 冰淇淋三明治—摩登時代”">​</a></h1><h3 id="android-4-0-冰淇淋三明治-——-摩登時代" tabindex="-1">Android 4.0 冰淇淋三明治 —— 摩登時代 <a class="header-anchor" href="#android-4-0-冰淇淋三明治-——-摩登時代" aria-label="Permalink to “Android 4.0 冰淇淋三明治 —— 摩登時代”">​</a></h3><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/samsung-i9250-galaxy-nexus-51.jpg" alt="三星 Galaxy Nexus，安卓4.0的首發設備。"></p><p><em>三星 Galaxy Nexus，安卓4.0的首發設備。</em></p><p>安卓 4.0，冰淇淋三明治，在 2011 年 10 月發佈，系統發佈回到正軌，帶來定期發佈的手機和平板，並且安卓再次開源。這是自薑餅以來手機設備的第一個更新，意味着最主要的安卓用户羣體近乎一年沒有見到更新了。4.0 隨處可見縮小版的蜂巢設計，還將虛擬按鍵，操作欄（Action Bar），全新的設計語言帶到了手機上。</p><p>冰淇淋三明治在三星 Galaxy Nexus 上首次亮相，也是最早帶有 720p 顯示屏的安卓手機之一。隨着分辨率的提高，Galaxy Nexus 使用了更大的 4.65 英寸顯示屏——幾乎比最初的 Nexus One 大了一整英寸。這被許多批評者認為“太大了”，但如今的安卓設備甚至更大。（5 英寸當今是“正常”的。）冰淇淋三明治比薑餅的性能要求更高，Galaxy Nexus 配備了一顆雙核，1.2Ghz 德州儀器 OMAP 處理器和 1GB 的內存。</p><p>在美國，Galaxy Nexus 在 Verizon 首發並且支持 LTE。不像之前的 Nexus 設備，最流行的型號——Verizon 版——是在運營商的控制之下，谷歌的軟件和更新在手機得到更新之前要經過 Verizon 的核準。這導致了更新的延遲以及 Verizon 不喜歡的應用被移除，即便是 Google Wallet 也不例外。</p><p>多虧了冰淇淋三明治的軟件改進，谷歌終於達成了移除手機上按鈕的目標。有了虛擬導航鍵，實體電容按鈕就可以移除了，最終 Galaxy Nexus 僅有電源和音量是實體按鍵。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/2home.png" alt="安卓 4.0 將很多蜂巢的設計縮小了。"></p><p><em>安卓 4.0 將很多蜂巢的設計縮小了。 [Ron Amadeo 供圖]</em></p><p>電子質感的審美在蜂巢中顯得有點多。於是在冰淇淋三明治中，谷歌開始減少科幻風的設計。科幻風的時鐘字體從半透明摺疊風格轉變成纖細，優雅，看起來更加正常的字體。解鎖環的水面波紋效果被去除了，蜂巢中的外星風格時鐘小部件也被極簡設計所取代。系統按鈕也經過了重新設計，原先的藍色輪廓，偶爾的厚邊框變成了細的，設置帶有白色輪廓。默認壁紙從蜂巢的藍色太空船內部變成條紋狀，破碎的彩虹，給默認佈局增添了不少遲來的色彩。</p><p>蜂巢的系統欄在手機上一分為二。在頂上是傳統的狀態欄，底部是新的系統欄，放着三個系統按鈕：後退、主屏幕、最近應用。一個固定的搜索欄放置在了主屏幕頂部。該欄以和底欄一樣的方式固定在屏幕上，所以在五個主屏上，它總共佔據了 20 個圖標大小的位置。在蜂巢的鎖屏上，內部的小圓圈可以向大圓圈外的任意位置滑動來解鎖設備。在冰淇淋三明治，你得把小圓圈移動到解鎖圖標上。這個新準確度要求允許谷歌向鎖屏添加新的選項：一個相機快捷方式。將小圓圈拖向相機圖標會直接啓動相機，跳過了主屏幕。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/appsandnotic40.png" alt="一個手機系統意味着更多的應用，通知面板重新回到了全屏界面。"></p><p><em>一個手機系統意味着更多的應用，通知面板重新回到了全屏界面。 [Ron Amadeo 供圖]</em></p><p>應用抽屜還是標籤頁式的，但是蜂巢中的“我的應用”標籤被“部件”標籤頁替代，這是個簡單的 2×3 部件略縮圖視圖。像蜂巢裏的那樣，這個應用抽屜是分頁的，需要水平滑動換頁。（如今安卓仍在使用這個應用抽屜設計。）應用抽屜裏新增的是 Google+ 應用，後來獨立存在。還有一個“Messenger”快捷方式，是 Google+ 的私密信息服務。（不要混淆 “Messenger” 和已有的 “Messaging” 短信應用。）</p><p>因為我們現在回到了手機上，所以短信，新聞和天氣，電話，以及語音撥號都回來了，以及 Cordy，一個平板的遊戲，被移除了。儘管不是 Nexus 設備，我們的截圖還是來自 Verizon 版的設備，可以從圖上看到有像 “My Verizon Mobile” 和 “VZ Backup Assistant” 這樣沒用的應用。為了和冰淇淋三明治的去電子風格主題一致，日曆和相機圖標現在看起來更像是來自地球的東西而不是來自外星球。時鐘，下載，電話，以及安卓市場同樣得到了新圖標，“聯繫人”獲得了新圖標，還有新名字 “People”。</p>',16)),n("p",null,[t[1]||(t[1]=o("通知面板進行了大改造，特別是和",-1)),r(e,{href:"http://cdn.arstechnica.net/wp-content/uploads/2014/02/32.png"},{default:d(()=>[...t[0]||(t[0]=[o("之前薑餅中的設計",-1)])]),_:1}),t[2]||(t[2]=o("相比而言。面板頭部有個日期，一個設置的快捷方式，以及“清除所有”按鈕。雖然蜂巢的第一個版本就允許用户通過通知右邊的“X”消除單個通知，但是冰淇淋三明治的實現更加優雅：只要從左向右滑動通知即可。蜂巢有着藍色高亮，但是藍色色調到處都是。冰淇淋三明治幾乎把所有地方的藍色統一成一個（如果你想知道確定的值，hex 碼是 ",-1)),t[3]||(t[3]=n("code",null,"#33B5E5",-1)),t[4]||(t[4]=o("）。通知面板的背景是透明的，底部的“把手”變為一個簡單的小藍圈，帶着不透明的黑色背景。",-1))]),t[20]||(t[20]=n("p",null,[n("img",{src:"http://cdn.arstechnica.net/wp-content/uploads/2014/03/market.png",alt:"安卓市場的主頁背景變成了黑色。"})],-1)),t[21]||(t[21]=n("p",null,[n("em",null,"安卓市場的主頁背景變成了黑色。 [Ron Amadeo 供圖]")],-1)),t[22]||(t[22]=n("p",null,"市場獲得了又一個新設計。它終於再次支持縱向模式，並且添加了音樂到商店中，你可以從中購買音樂。新的市場拓展了從蜂巢中引入的卡片概念，它還是第一個同時使用在手機和平板上的版本。主頁上的卡片通常不是鏈接到應用的，而是指向特別的促銷頁面，像是“編輯精選”或季度促銷。",-1)),t[23]||(t[23]=n("hr",null,null,-1)),t[24]||(t[24]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2016/05/r.amadeo-45843.jpg",alt:"Ron Amadeo"})],-1)),n("p",null,[r(e,{href:"http://arstechnica.com/author/ronamadeo"},{default:d(()=>[...t[5]||(t[5]=[o("Ron Amadeo",-1)])]),_:1}),t[7]||(t[7]=o(" / Ron是Ars Technica的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1)),r(e,{href:"https://twitter.com/RonAmadeo"},{default:d(()=>[...t[6]||(t[6]=[o("@RonAmadeo",-1)])]),_:1})]),t[25]||(t[25]=n("hr",null,null,-1)),n("p",null,[t[9]||(t[9]=o("via: ",-1)),r(e,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/19/"},{default:d(()=>[...t[8]||(t[8]=[o("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/19/",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=o("譯者：",-1)),r(e,{href:"https://github.com/alim0x"},{default:d(()=>[...t[10]||(t[10]=[o("alim0x",-1)])]),_:1}),t[13]||(t[13]=o(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:d(()=>[...t[11]||(t[11]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=o("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...t[14]||(t[14]=[o("LCTT",-1)])]),_:1}),t[17]||(t[17]=o(" 原創翻譯，",-1)),r(e,{href:"http://linux.cn/"},{default:d(()=>[...t[15]||(t[15]=[o("Linux中國",-1)])]),_:1}),t[18]||(t[18]=o(" 榮譽推出",-1))])])}const N=i(u,[["render",m]]);export{C as __pageData,N as default};
